interface Product {
  name: string;
  price: number;
  category: string;
}

const products: Product[] = [
  { name: 'Laptop', price: 1200, category: 'Electronics' },
  { name: 'Book', price: 20, category: 'Education' },
  { name: 'Pen', price: 5, category: 'Stationery' },
  { name: 'Headphones', price: 45, category: 'Electronics' },
  { name: 'Coffee Mug', price: 15, category: 'Kitchen' }
];

function filterAffordable(products: Product[]): Product[] {
  return products.filter(p => p.price < 50);
}

const affordable = filterAffordable(products);
